def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the uniform separator and split into two equal-sized panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            a, b = grid[:r], grid[r + 1:]
            return [[3 if a[i][j] == 5 and b[i][j] == 5 else 5
                     for j in range(w)] for i in range(r)]

    for c in range(w):
        if len({row[c] for row in grid}) == 1 and c == w - c - 1:
            return [[3 if grid[i][j] == 5 and grid[i][j + c + 1] == 5 else 5
                     for j in range(c)] for i in range(h)]

    return grid
